using System.Diagnostics;
using System.Globalization;
using System.Text.Json;

// A self-limiting generated byte source for child-process transport tests.
_ = Task.Run(async () => { await Task.Delay(TimeSpan.FromSeconds(20)); Environment.Exit(99); });
if (args.Contains("-i") && args.Contains("-W"))
{
    // Decoder-shaped transport fixture: it returns generated input bytes, without decoding retail formats.
    var receiptPath = Environment.GetEnvironmentVariable("DEVIANT_TEST_BINARY_INVOCATION")
        ?? throw new InvalidOperationException("The generated decoder fixture needs a receipt path.");
    using (var self = Process.GetCurrentProcess())
    {
        var receipt = JsonSerializer.Serialize(new { Arguments = args, ProcessId = self.Id, StartTimeUtcTicks = self.StartTime.ToUniversalTime().Ticks });
        var staging = receiptPath + ".writing";
        await File.WriteAllTextAsync(staging, receipt);
        File.Move(staging, receiptPath);
    }
    if (args.Contains("-o") || !args.Contains("-p")) return 23;
    using var input = new FileStream(args[^1], FileMode.Open, FileAccess.Read, FileShare.Read);
    if (input.Length is <= 0 or > 1024 * 1024) return 24;
    var generated = new byte[checked((int)input.Length)];
    await input.ReadExactlyAsync(generated);
    var binaryOutput = Console.OpenStandardOutput();
    await binaryOutput.WriteAsync(generated);
    await binaryOutput.FlushAsync();
    if (int.TryParse(Environment.GetEnvironmentVariable("DEVIANT_TEST_BINARY_LINGER_MS"), out var delay))
        await Task.Delay(Math.Clamp(delay, 0, 10_000));
    return int.TryParse(Environment.GetEnvironmentVariable("DEVIANT_TEST_BINARY_EXIT"), out var result) ? Math.Clamp(result, 0, 125) : 0;
}
var count = long.Parse(args[0], CultureInfo.InvariantCulture);
var errorCount = int.Parse(args[1], CultureInfo.InvariantCulture);
var linger = int.Parse(args[2], CultureInfo.InvariantCulture);
var exitCode = int.Parse(args[3], CultureInfo.InvariantCulture);
using (var self = Process.GetCurrentProcess())
    await File.WriteAllTextAsync(args[4], $"{self.Id}:{self.StartTime.ToUniversalTime().Ticks}");
var stderr = Task.Run(async () =>
{
    var block = new string('e', 8192);
    for (var remaining = errorCount; remaining > 0; remaining -= Math.Min(remaining, block.Length))
        await Console.Error.WriteAsync(block.AsMemory(0, Math.Min(remaining, block.Length)));
    await Console.Error.FlushAsync();
});
var output = Console.OpenStandardOutput();
var bytes = new byte[8192];
for (long offset = 0; offset < count;)
{
    var take = (int)Math.Min(count - offset, bytes.Length);
    for (var index = 0; index < take; index++) bytes[index] = (byte)((offset + index) % 251);
    await output.WriteAsync(bytes.AsMemory(0, take));
    offset += take;
}
await output.FlushAsync();
await stderr;
if (linger > 0) await Task.Delay(linger);
return exitCode;
